BEGIN TRANSACTION;
CREATE TRIGGER chengdu_deposit_messages_after_insert
AFTER INSERT ON messages
BEGIN
  UPDATE folders
  SET message_count = message_count + 1,
      unread_count = unread_count + CASE WHEN NEW.is_read = 0 THEN 1 ELSE 0 END
  WHERE id = NEW.folder_id;
END;
CREATE TRIGGER chengdu_deposit_messages_after_delete
AFTER DELETE ON messages
BEGIN
  UPDATE folders
  SET message_count = message_count - 1,
      unread_count = unread_count - CASE WHEN OLD.is_read = 0 THEN 1 ELSE 0 END
  WHERE id = OLD.folder_id;
END;
CREATE TRIGGER chengdu_deposit_messages_after_move_or_read
AFTER UPDATE OF folder_id, is_read ON messages
BEGIN
  UPDATE folders
  SET message_count = message_count - 1,
      unread_count = unread_count - CASE WHEN OLD.is_read = 0 THEN 1 ELSE 0 END
  WHERE id = OLD.folder_id;
  UPDATE folders
  SET message_count = message_count + 1,
      unread_count = unread_count + CASE WHEN NEW.is_read = 0 THEN 1 ELSE 0 END
  WHERE id = NEW.folder_id;
END;
-- detail 2026-06-01 ofdetailrecord；attachmentdetailforshoulddetail、detailoractivitydetail。

COMMIT;
